local shape_chunks = {}
for i = 1, 5 do
  shape_chunks[i] = MODULE .. string.format(".shapes_%03d", i)
end

local where -- shape name -> file number, built on the first lookup

-- The registry: a lookup of a shape not loaded yet loads its whole file. An unknown name is nil. A
-- missing file raises, as a missing module does.
local shapes = setmetatable({}, {
  __index = function(registry, name)
    if where == nil then
      where = {}
      for file, shape in string.gmatch(SHAPES, "(%d+) ([^\n]+)") do
        where[shape] = file
      end
      SHAPES = nil
    end
    local file = where[name]
    if file == nil then
      return nil
    end
    for k, node in pairs(require(MODULE .. ".shapes_" .. file)) do
      rawset(registry, k, node)
    end
    return rawget(registry, name)
  end,
})

local classes = {}

classes.CatalogSyncNotFound = errors.define({
  tag = "CatalogSyncNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})
classes.CloudIntegrationNotFound = errors.define({
  tag = "CloudIntegrationNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})
classes.FeatureNotEnabled = errors.define({
  tag = "FeatureNotEnabled",
  categories = {},
  matchers = {
    { code = 1012, status = 403 },
    { status = 404, message = { includes = "No route for that URI" } },
  },
  fields = { "code", "message" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = {},
  matchers = { { status = 403 } },
  fields = { "code", "message" },
})
classes.OnRampNotFound = errors.define({
  tag = "OnRampNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})

local ops = {}
for i = 1, 1 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "cloudflare.magic_cloud_networking",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "cloudflare-api",
    prefix = "Cloudflare",
    service = "MagicCloudNetworking",
    labels = "cloudflare",
    propagate = "w3c",
    response_headers = {
      { header = "x-request-id", name = "http.response.header.x-request-id", transform = "list" },
      { header = "request-id", name = "http.response.header.request-id", transform = "list" },
      { header = "cf-ray", name = "http.response.header.cf-ray", transform = "list" },
    },
  },
}
